/*
 * prog47_circular_queue.c
 *
 * Re‑implementation of the original program (the binary was heavily
 * obfuscated).  The program implements a circular queue of capacity 5
 * and processes commands supplied on the command line.
 *
 * Observable behaviour (stdout) reproduced:
 *
 *   NOOP                – printed when the program is invoked without
 *                         any command‑line arguments.
 *
 *   ENQ <value>         – printed after a successful enqueue.
 *
 *   DEQ <value>         – printed after a successful dequeue.
 *
 *   FRONT <value>       – printed when the front element is queried.
 *
 *   EMPTY               – printed when the queue is empty (either by an
 *                         explicit EMPTY command, or when DEQ/FRONT is
 *                         attempted on an empty queue).
 *
 *   FULL                – printed when an enqueue is attempted while the
 *                         queue already contains 5 elements.
 *
 *   ERR                 – printed for any malformed command or for a
 *                         failed numeric conversion.
 *
 * The command syntax accepted by the original program (as inferred from
 * the decompiled state‑machine) is:
 *
 *   E<number>   – enqueue the signed decimal integer <number>.
 *   D           – dequeue the front element.
 *   F           – print the front element.
 *   EMPTY       – query emptiness (just prints "EMPTY").
 *
 * Any other argument results in "ERR".
 *
 * The implementation below follows the same logic, using a simple
 * circular buffer of five 64‑bit integers.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define CAPACITY 5

static long items[CAPACITY];
static int  head   = 0;   /* index of the front element */
static int  count  = 0;   /* number of elements currently stored */

/* Helper: check whether a string consists only of an optional sign
 * followed by decimal digits. */
static int is_number(const char *s)
{
    if (*s == '+' || *s == '-') s++;
    if (!*s) return 0;
    while (*s) {
        if (!isdigit((unsigned char)*s)) return 0;
        s++;
    }
    return 1;
}

/* Enqueue operation – prints the required message. */
static void do_enqueue(long v)
{
    if (count == CAPACITY) {
        puts("FULL");
        return;
    }
    items[(head + count) % CAPACITY] = v;
    ++count;
    printf("ENQ %ld\n", v);
}

/* Dequeue operation – prints the required message. */
static void do_dequeue(void)
{
    if (count == 0) {
        puts("EMPTY");
        return;
    }
    long v = items[head];
    head = (head + 1) % CAPACITY;
    --count;
    printf("DEQ %ld\n", v);
}

/* Front query – prints the required message. */
static void do_front(void)
{
    if (count == 0) {
        puts("EMPTY");
        return;
    }
    printf("FRONT %ld\n", items[head]);
}

/* Empty query – always prints "EMPTY". */
static void do_empty(void)
{
    puts("EMPTY");
}

/* Process a single command argument. */
static void process_arg(const char *arg)
{
    if (arg[0] == 'E' && arg[1] != '\0') {               /* ENQ */
        if (!is_number(arg + 1)) {
            puts("ERR");
            return;
        }
        long v = strtol(arg + 1, NULL, 10);
        do_enqueue(v);
    }
    else if (strcmp(arg, "D") == 0) {                  /* DEQ */
        do_dequeue();
    }
    else if (strcmp(arg, "F") == 0) {                  /* FRONT */
        do_front();
    }
    else if (strcmp(arg, "EMPTY") == 0) {              /* EMPTY command */
        do_empty();
    }
    else {
        puts("ERR");
    }
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        process_arg(argv[i]);
    }
    return 0;
}
